<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';import {AutomationsClient,AutomationError,type ProviderSetup,type Connection,type Authorization,type ConnectionOptions} from './automations-client';import AutomationConnectionCard from './AutomationConnectionCard.svelte';import './automations.css';
 export let companyId:string;export let actorId:string;export let conversationId:string;export let providerId:'slack'|'shopify';export let accessSignal:AbortSignal;export let requestedScopes:string[]=[];
 const dispatch=createEventDispatcher<{close:void;denied:{status:number};changed:{companyId:string;conversationId:string;providerId:string;connected:boolean}}>();
 let mounted=false,scope='',watched:AbortSignal|undefined,client:AutomationsClient|undefined,generation=0,session='',setup:ProviderSetup|null=null,connection:Connection|null=null,canManage=false,busy=false,loading=true,error='',authorization:Authorization|null=null;
 $: if(mounted&&(scope!==companyId+'\0'+actorId+'\0'+conversationId+'\0'+providerId||watched!==accessSignal)){reset();scope=companyId+'\0'+actorId+'\0'+conversationId+'\0'+providerId;watched=accessSignal;watched.addEventListener('abort',lost,{once:true});if(watched.aborted)lost();else{session=localStorage.getItem('token')||'';client=new AutomationsClient(companyId,()=>localStorage.getItem('token')||'',watched);void load();}}
 function reset(){generation++;client?.close();client=undefined;watched?.removeEventListener('abort',lost);setup=null;connection=null;authorization=null;canManage=false;busy=false;loading=true;error='';}
 function lost(){reset();loading=false;dispatch('close');}
 function fail(cause:unknown){if(cause instanceof AutomationError&&(cause.status===401||cause.status===403)){lost();dispatch('denied',{status:cause.status});return;}error=cause instanceof Error?cause.message:'The company connection could not be checked.';}
 async function load(clearAuthorization=true){if(!client)return;const current=client,n=generation;loading=true;error='';try{const [settings,connections]=await Promise.all([current.connectionSetup(),current.connections()]);if(n!==generation)return;setup=settings.providers.find(p=>p.providerId===providerId)||null;canManage=settings.actions.canManage;connection=connections.find(c=>c.providerId===providerId&&c.status==='CONNECTED')||null;if(clearAuthorization||connection)authorization=null;dispatch('changed',{companyId,conversationId,providerId,connected:!!connection});}catch(e){if(n===generation)fail(e);}finally{if(n===generation)loading=false;}}
 async function connect(options:ConnectionOptions){if(!client||busy||!canManage)return;const current=client,n=generation;busy=true;error='';try{const result=await current.authorize(providerId,conversationId,undefined,{shopDomain:options.shopDomain,expectedSetupRevision:options.expectedSetupRevision});if(n!==generation)return;authorization=result;await load(false);}catch(e){if(n===generation)fail(e);}finally{if(n===generation)busy=false;}}
 function checkSession(){if(client&&session!==(localStorage.getItem('token')||''))lost();}
 function focused(){checkSession();if(client)void load();}
 function storage(e:StorageEvent){if(e.key==='token'||e.key===null)lost();}
 onMount(()=>{mounted=true;window.addEventListener('focus',focused);window.addEventListener('storage',storage);const timer=setInterval(checkSession,500);return()=>clearInterval(timer);});onDestroy(()=>{reset();window.removeEventListener('focus',focused);window.removeEventListener('storage',storage);});
</script>
<section class="starli-automations chat-connection" aria-label="Company integration connection"><div class="sa-heading"><span class="sa-eyebrow">STARLI INTEGRATIONS</span><button on:click={()=>dispatch('close')}>Close</button></div>{#if loading&&!setup}<p class="sa-muted" role="status">Checking the saved company connection…</p>{/if}{#if error}<p class="sa-error" role="alert">{error}</p>{/if}{#if connection}<h3>{providerId==='slack'?'Slack':'Shopify'} company account connected</h3><p class="sa-muted">{connection.displayName} · {connection.accountIdentity}</p><p class="sa-muted">Authorized bots reuse this company connection. Your conversation remains here.</p><button disabled={busy||loading} on:click={()=>void load()}>Check connection</button>{:else}<AutomationConnectionCard {providerId} providerName={providerId==='slack'?'Slack':'Shopify'} {requestedScopes} {setup} {canManage} {busy} {authorization} on:connect={event=>connect(event.detail)} on:refresh={()=>void load()}/>{/if}</section>
<style>.chat-connection{width:100%;max-width:740px;border:1px solid #e6ebf4;border-radius:12px;padding:20px;background:#fafbfd;margin:12px 0}.chat-connection>.sa-heading{align-items:center}.chat-connection :global(.sa-connect){margin-top:12px}.chat-connection>.sa-heading .sa-eyebrow{margin:0}@media(max-width:500px){.chat-connection{padding:15px}}</style>
